<?php/** * Module: Notifications * File: /ok-public/tabs/notification.php */if (!defined('OK_LOADED')) exit;// ---------------------------------------------------------// 1. AJAX HANDLER (მუშავდება როცა JS აგზავნის მოთხოვნას)// ---------------------------------------------------------if (isset($_GET['action']) && strpos($_GET['action'], 'ajax_mark_') === 0) {        if (session_status() === PHP_SESSION_NONE) { session_start(); }    // DB კლასის მოძიება    if (!class_exists('OK_DB') && file_exists(__DIR__ . '/../../load.php')) {        // require_once __DIR__ . '/../../load.php';     }    if (isset($_SESSION['user_id'])) {        global $ok_db;        $db = (class_exists('OK_DB')) ? OK_DB::instance() : $ok_db;                $uid = (int)$_SESSION['user_id'];        $response = ['success' => false];        // ა) ერთი შეტყობინების წაკითხვა        if ($_GET['action'] === 'ajax_mark_read' && isset($_GET['nid'])) {            $nid = (int)$_GET['nid'];                        // ლოგიკა: ვამატებთ მომხმარებლის ID-ს read_by_users ველში (მძიმით გამოყოფილი)            $sql = "UPDATE ok_notifications                     SET read_by_users = IF(read_by_users IS NULL OR read_by_users = '', ?, CONCAT(read_by_users, ',', ?))                     WHERE id = ?                     AND FIND_IN_SET(?, for_user_id)                     AND NOT FIND_IN_SET(?, IFNULL(read_by_users, ''))";                        $db->query($sql, [$uid, $uid, $nid, $uid, $uid]);            $response['success'] = true;        // ბ) ყველას წაკითხვა        } elseif ($_GET['action'] === 'ajax_mark_all_read') {            $sql = "UPDATE ok_notifications                     SET read_by_users = IF(read_by_users IS NULL OR read_by_users = '', ?, CONCAT(read_by_users, ',', ?))                     WHERE FIND_IN_SET(?, for_user_id)                     AND NOT FIND_IN_SET(?, IFNULL(read_by_users, ''))";                        $db->query($sql, [$uid, $uid, $uid, $uid]);            $response['success'] = true;        }                header('Content-Type: application/json');        echo json_encode($response);        exit; // ვწყვეტთ სკრიპტს    }}// ---------------------------------------------------------// 2. რენდერის ფუნქცია (ვიზუალი)// ---------------------------------------------------------function ok_render_notifications_tab_content($user) {    global $ok_db;    $db = (class_exists('OK_DB')) ? OK_DB::instance() : $ok_db;    $uid = (int)$user->id;         // 50 შეტყობინების წამოღება    // is_read_by_me ველს ვქმნით დინამიურად FIND_IN_SET-ით    $sql = "SELECT *, FIND_IN_SET(?, IFNULL(read_by_users, '')) as is_read_by_me             FROM ok_notifications             WHERE FIND_IN_SET(?, for_user_id)             ORDER BY created_at DESC LIMIT 50";                $all_notifs = $db->get_results($sql, [$uid, $uid]);    ?>        <style>        .ok-notif-item { display: flex; align-items: start; padding: 15px; border-bottom: 1px solid #f0f0f0; transition: 0.2s; cursor: pointer; border-radius: 8px; margin-bottom: 5px; }        .ok-notif-item:hover { background-color: #f8f9fa; }        .ok-notif-item.unread { background-color: #f0f8ff; border-left: 3px solid #0d6efd; }                .ok-notif-icon { width: 35px; height: 35px; background: #eef2ff; color: #4f46e5; border-radius: 8px; display: flex; align-items: center; justify-content: center; font-size: 1.1rem; margin-right: 15px; flex-shrink: 0; }        .ok-notif-body { flex-grow: 1; }        .ok-notif-text { font-size: 0.95rem; color: #333; line-height: 1.4; margin-bottom: 5px; }        .ok-notif-date { font-size: 0.75rem; color: #999; }        .ok-notif-dot { width: 8px; height: 8px; background: #0d6efd; border-radius: 50%; margin-top: 8px; margin-left: 10px; display: none; }        .unread .ok-notif-dot { display: block; }    </style>    <div class="ok-card p-0" style="border: none; box-shadow: none;">        <div class="d-flex justify-content-between align-items-center mb-4 pb-2 border-bottom">            <h5 class="m-0 fw-bold text-dark"><i class="bi bi-bell-fill text-primary me-2"></i> შეტყობინებები</h5>            <button class="btn btn-sm btn-light text-primary fw-bold" onclick="okMarkAllReadTab(this)">                <i class="bi bi-check2-all"></i> ყველას წაკითხვა            </button>        </div>                <div class="ok-notif-container">            <?php if ($all_notifs): ?>                <?php foreach ($all_notifs as $note):                     $is_unread = ($note->is_read_by_me == 0) ? 'unread' : '';                                        // აიკონები ტიპის მიხედვით                    $type = $note->type ?? 'info';                    $icon = 'bi-info-circle'; $bg = '#eef5ff'; $col = '#0d6efd';                                        if($type == 'success') { $icon = 'bi-check-circle'; $bg = '#e6f8f0'; $col = '#198754'; }                    if($type == 'warning') { $icon = 'bi-exclamation-triangle'; $bg = '#fff8e6'; $col = '#fd7e14'; }                    if($type == 'danger')  { $icon = 'bi-x-circle'; $bg = '#fceceb'; $col = '#dc3545'; }                ?>                    <div class="ok-notif-item <?php echo $is_unread; ?>" id="tab-notif-<?php echo $note->id; ?>"                         onclick="okHandleTabClick(<?php echo $note->id; ?>, '<?php echo htmlspecialchars($note->link ?? ''); ?>')">                                                <div class="ok-notif-icon" style="background: <?php echo $bg; ?>; color: <?php echo $col; ?>;">                            <i class="bi <?php echo $icon; ?>"></i>                        </div>                                                <div class="ok-notif-body">                            <div class="ok-notif-text"><?php echo $note->message; // HTML დაშვებულია ?></div>                            <div class="ok-notif-date">                                <i class="bi bi-clock me-1"></i> <?php echo date('d M Y, H:i', strtotime($note->created_at)); ?>                            </div>                        </div>                                                <div class="ok-notif-dot"></div>                    </div>                <?php endforeach; ?>            <?php else: ?>                <div class="text-center py-5 text-muted">                    <i class="bi bi-bell-slash fs-1 opacity-25 d-block mb-3"></i>                    თქვენ არ გაქვთ ახალი შეტყობინებები.                </div>            <?php endif; ?>        </div>    </div>        <script>        // კლიკზე წაკითხულად მონიშვნა და გადასვლა        function okHandleTabClick(nid, link) {            const row = document.getElementById('tab-notif-' + nid);                        // თუ წაუკითხავია, გავგზავნოთ AJAX            if (row && row.classList.contains('unread')) {                row.classList.remove('unread');                fetch('?action=ajax_mark_read&nid=' + nid, { method: 'GET' });            }                        // თუ ლინკი აქვს, გადავიდეთ            if (link && link !== '#' && link !== '') {                setTimeout(() => { window.location.href = link; }, 50); // მცირე დაყოვნება UX-ისთვის            }        }        // ყველას წაკითხვა        function okMarkAllReadTab(btn) {            const oldHtml = btn.innerHTML;            btn.innerHTML = '<span class="spinner-border spinner-border-sm"></span>';                        fetch('?action=ajax_mark_all_read')                .then(r => r.json())                .then(d => {                    if(d.success) {                        document.querySelectorAll('.ok-notif-item').forEach(el => el.classList.remove('unread'));                    }                    btn.innerHTML = '<i class="bi bi-check2-all"></i> მზადაა';                    setTimeout(() => btn.innerHTML = oldHtml, 2000);                })                .catch(err => {                    btn.innerHTML = 'Error';                });        }    </script>    <?php}// ---------------------------------------------------------// 3. რეგისტრაცია (ეს აკავშირებს ფაილს პროფილის სისტემასთან)// ---------------------------------------------------------if (function_exists('add_ok_action')) {        add_ok_action('init_profile_tabs', function() {                // ვამოწმებთ, რომ პროფილის სისტემა მზად არის        if (function_exists('add_ok_profile_tab')) {            add_ok_profile_tab(                'notifications',                  // Slug (ID URL-ში)                'შეტყობინებები',                  // სათაური                'bi-bell',                        // აიკონი (Bootstrap)                'ok_render_notifications_tab_content', // ფუნქციის სახელი (ზემოთ რაც დავწერეთ)                20                                // რიგითობა            );        }            });}?>